{
  "$schema": "https://open-design.ai/schemas/plugin.v1.json",
  "specVersion": "1.0.0",
  "name": "direction-picker",
  "title": "Direction picker",
  "version": "0.1.0",
  "description": "3-5 direction picker that lets the user choose before final generation.",
  "license": "MIT",
  "author": {
    "name": "Open Design",
    "url": "https://github.com/nexu-io"
  },
  "homepage": "https://github.com/nexu-io/open-design/tree/main/plugins/_official/atoms/direction-picker",
  "tags": [
    "atom",
    "first-party",
    "planning"
  ],
  "compat": {
    "agentSkills": [
      {
        "path": "./SKILL.md"
      }
    ]
  },
  "od": {
    "kind": "atom",
    "scenario": "general",
    "mode": "planning",
    "capabilities": [
      "prompt:inject"
    ]
  }
}
